// AP5 actual width2816 R1/R3 postnorm replay. Diagnostic timings only.
#include <cuda_runtime.h>
#include <algorithm>
#include <bit>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <limits>
#include <stdexcept>
#include <string>
#include <vector>
#define ARGS const float*,const std::uint16_t*,const float*,float*,float*,unsigned,float,const std::uint16_t*,cudaStream_t
extern "C" cudaError_t ap5_parent(ARGS);
extern "C" cudaError_t ap5_candidate(ARGS);
extern "C" cudaError_t ap5_resources(cudaFuncAttributes*,cudaFuncAttributes*);
namespace {
void Check(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
struct Device {
 void* raw=nullptr;void* p=nullptr;std::size_t size;
 explicit Device(std::size_t n):size(n){Check(cudaMalloc(&raw,n+256));p=static_cast<char*>(raw)+128;reset();}
 ~Device(){if(raw)(void)cudaFree(raw);}
 void reset(){Check(cudaMemset(raw,0xa5,size+256));}
 template<class T>T* as(){return static_cast<T*>(p);}
 std::vector<char> bytes(){std::vector<char>b(size);Check(cudaMemcpy(b.data(),p,size,cudaMemcpyDeviceToHost));return b;}
 void guards(){unsigned char b[256];Check(cudaMemcpy(b,raw,128,cudaMemcpyDeviceToHost));Check(cudaMemcpy(b+128,static_cast<char*>(p)+size,128,cudaMemcpyDeviceToHost));for(auto c:b)if(c!=0xa5)throw std::runtime_error("postnorm guard changed");}
};
std::vector<char> Read(const std::filesystem::path& p,std::size_t n){
 if(!std::filesystem::is_regular_file(std::filesystem::symlink_status(p))||std::filesystem::file_size(p)!=n)throw std::runtime_error("postnorm capture extent/type mismatch");
 std::vector<char>b(n);std::ifstream f(p,std::ios::binary);f.read(b.data(),n);if(!f||f.peek()!=EOF)throw std::runtime_error("postnorm capture read failed");return b;
}
void Upload(Device& d,const std::vector<char>& b){if(d.size!=b.size())throw std::runtime_error("upload size mismatch");Check(cudaMemcpy(d.p,b.data(),b.size(),cudaMemcpyHostToDevice));}
}
int main(int argc,char** argv){
 try {
  if(argc!=4)return 2;
  const bool boundaries=std::string(argv[2])=="boundaries";
  std::ifstream manifest(argv[1]);if(!manifest)throw std::runtime_error("missing postnorm manifest");
  if(std::filesystem::exists(argv[3]))throw std::runtime_error("postnorm output exists");
  cudaFuncAttributes pa{},ca{};Check(ap5_resources(&pa,&ca));
  std::ofstream result(argv[3]);result.precision(9);
  result<<"{\"diagnostic_only\":true,\"resources\":{\"parent_registers\":"<<pa.numRegs<<",\"candidate_registers\":"<<ca.numRegs<<",\"parent_static_shared\":"<<pa.sharedSizeBytes<<",\"candidate_static_shared\":"<<ca.sharedSizeBytes<<",\"parent_local_bytes\":"<<pa.localSizeBytes<<",\"candidate_local_bytes\":"<<ca.localSizeBytes<<"},\"cases\":[";
  std::string root,stem;unsigned rows,epsilon_bits,normalized_present,cases=0;
  while(manifest>>root>>stem>>rows>>epsilon_bits>>normalized_present){
   if(cases>=32 || (rows!=1&&rows!=3))throw std::runtime_error("postnorm case geometry invalid");
   const auto n=rows*2816U*4U;
   Device input(n),residual(n),weight(5632),pn(n),po(n),cn(n),co(n),scalar(2);
   auto file=[&](const char* part){return std::filesystem::path(root)/(stem+"-"+part+".bin");};
   const auto original_input=Read(file("input"),n),original_residual=Read(file("residual"),n);
   Upload(input,original_input);Upload(residual,original_residual);Upload(weight,Read(file("weight"),5632));
   const float epsilon=std::bit_cast<float>(epsilon_bits);
   const bool actual_normalized=normalized_present!=0;
   auto launch=[&](bool child,bool norm=true,int alias=0,bool use_scalar=false,cudaStream_t stream=nullptr,bool use_weight=true){
    auto f=child?ap5_candidate:ap5_parent;auto& output=child?co:po;auto& normalized=child?cn:pn;
    float* destination=alias==1?input.as<float>():alias==2?residual.as<float>():output.as<float>();
    Check(f(input.as<float>(),use_weight?weight.as<std::uint16_t>():nullptr,residual.as<float>(),norm?normalized.as<float>():nullptr,destination,rows,epsilon,use_scalar?scalar.as<std::uint16_t>():nullptr,stream));
   };
   launch(false,actual_normalized);launch(true,actual_normalized);Check(cudaDeviceSynchronize());
   if(pn.bytes()!=cn.bytes()||po.bytes()!=co.bytes()||po.bytes()!=Read(file("output"),n))throw std::runtime_error("actual postnorm bit mismatch");
   if(std::filesystem::exists(file("normalized"))&&pn.bytes()!=Read(file("normalized"),n))throw std::runtime_error("actual normalized bits mismatch");
   std::vector<float> parent,child;
   if(!boundaries){
    cudaStream_t stream{};Check(cudaStreamCreate(&stream));cudaEvent_t a{},b{};Check(cudaEventCreate(&a));Check(cudaEventCreate(&b));
    auto graph=[&](bool candidate){cudaGraph_t g{};Check(cudaStreamBeginCapture(stream,cudaStreamCaptureModeThreadLocal));for(unsigned i=0;i<128;++i)launch(candidate,actual_normalized,0,false,stream);Check(cudaStreamEndCapture(stream,&g));cudaGraphExec_t e{};Check(cudaGraphInstantiate(&e,g,0ULL));Check(cudaGraphDestroy(g));return e;};
    auto pg=graph(false),cg=graph(true);
    auto measure=[&](bool candidate){Check(cudaEventRecord(a,stream));Check(cudaGraphLaunch(candidate?cg:pg,stream));Check(cudaEventRecord(b,stream));Check(cudaEventSynchronize(b));float ms;Check(cudaEventElapsedTime(&ms,a,b));return ms*1000/128;};
    for(unsigned i=0;i<3;++i){(void)measure(false);(void)measure(true);}
    for(unsigned i=0;i<10;++i){float p,c;if(i%2){c=measure(true);p=measure(false);}else{p=measure(false);c=measure(true);}parent.push_back(p);child.push_back(c);}
    Check(cudaGraphExecDestroy(pg));Check(cudaGraphExecDestroy(cg));Check(cudaEventDestroy(a));Check(cudaEventDestroy(b));Check(cudaStreamDestroy(stream));
   } else {
    for(bool norm:{false,true})for(int alias:{0,1,2})for(std::uint16_t bits:{std::uint16_t(0x3f00),std::uint16_t(0x3f80),std::uint16_t(0xbf80)}){
     Check(cudaMemcpy(scalar.p,&bits,2,cudaMemcpyHostToDevice));
     Upload(input,original_input);Upload(residual,original_residual);launch(false,norm,alias,true);Check(cudaDeviceSynchronize());
     const auto expected=alias==1?input.bytes():alias==2?residual.bytes():po.bytes();const auto expected_norm=pn.bytes();
     Upload(input,original_input);Upload(residual,original_residual);launch(true,norm,alias,true);Check(cudaDeviceSynchronize());
     if(expected!=(alias==1?input.bytes():alias==2?residual.bytes():co.bytes())||(norm&&expected_norm!=cn.bytes()))throw std::runtime_error("scalar/alias postnorm mismatch");
    }
    for(float value:{0.0F,-0.0F,std::numeric_limits<float>::denorm_min(),std::numeric_limits<float>::min(),1.e-20F,1.e10F,std::numeric_limits<float>::max()})for(bool use_weight:{false,true}){
     std::vector<float> finite(n/4);
     for(std::size_t i=0;i<finite.size();++i)finite[i]=(i%2?value:-value);
     Check(cudaMemcpy(input.p,finite.data(),n,cudaMemcpyHostToDevice));Upload(residual,original_residual);
     launch(false,true,0,false,nullptr,use_weight);launch(true,true,0,false,nullptr,use_weight);Check(cudaDeviceSynchronize());
     if(pn.bytes()!=cn.bytes()||po.bytes()!=co.bytes())throw std::runtime_error("finite-extreme/null-weight postnorm mismatch");
    }
   }
   for(auto* d:{&input,&residual,&weight,&pn,&po,&cn,&co,&scalar})d->guards();
   result<<(cases?",":"")<<"{\"stem\":\""<<stem<<"\",\"rows\":"<<rows<<",\"consumed_outputs_bit_exact\":true,\"parent_us\":[";for(unsigned i=0;i<parent.size();++i)result<<(i?",":"")<<parent[i];result<<"],\"candidate_us\":[";for(unsigned i=0;i<child.size();++i)result<<(i?",":"")<<child[i];result<<"]}";++cases;
  }
  result<<"]}\n";if(!cases||!result||!manifest.eof())throw std::runtime_error("postnorm manifest/output incomplete");
  std::fprintf(stderr,"AP5 %u actual postnorm cases exact%s\n",cases,boundaries?", scalar/alias matrix checked":"");return 0;
 } catch(const std::exception& e){std::fprintf(stderr,"AP5: %s\n",e.what());return 1;}
}
